/* ============ apply / persist logic (URL param, no storage) ============ */
function btrGetLang(){
  const p = new URLSearchParams(window.location.search).get('lang');
  return (p === 'ca' || p === 'en') ? p : 'es';
}
function btrApplyLang(lang){
  const dict = I18N[lang] || I18N.es;
  document.documentElement.lang = lang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const k = el.getAttribute('data-i18n');
    if(dict[k] != null) el.textContent = dict[k];
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el=>{
    const k = el.getAttribute('data-i18n-html');
    if(dict[k] != null) el.innerHTML = dict[k];
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{
    const k = el.getAttribute('data-i18n-ph');
    if(dict[k] != null) el.setAttribute('placeholder', dict[k]);
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el=>{
    const k = el.getAttribute('data-i18n-title');
    if(dict[k] != null) el.setAttribute('title', dict[k]);
  });
  document.querySelectorAll('.lang__link').forEach(a=>{
    const on = a.dataset.lang === lang;
    a.classList.toggle('on', on);
    a.setAttribute('aria-current', on ? 'true' : 'false');
  });
}
function btrUpdateLinks(lang){
  document.querySelectorAll('a[href]').forEach(a=>{
    if(a.classList.contains('lang__link')) return;
    const href = a.getAttribute('href');
    if(!href || /^https?:\/\//.test(href) || href.startsWith('mailto:') || href.startsWith('tel:') || href.startsWith('#')) return;
    if(!/\.html/.test(href)) return;
    const [pathPart, hashPart] = href.split('#');
    const file = pathPart.split('?')[0];
    a.setAttribute('href', file + '?lang=' + lang + (hashPart ? '#' + hashPart : ''));
  });
}
function btrBuildSwitcher(lang){
  const file = window.location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.lang__link').forEach(a=>{
    a.setAttribute('href', file + '?lang=' + a.dataset.lang);
  });
}
(function(){
  const lang = btrGetLang();
  btrApplyLang(lang);
  btrUpdateLinks(lang);
  btrBuildSwitcher(lang);
})();
